SELECT
	homepage_id, facility_idx, facility_req_idx, apply_id,
	apply_name, apply_phone, apply_desc, apply_status,
	add_date, add_id, modify_date, modify_id
FROM
	FACILITY_REQ
WHERE
	homepage_id = #{homepage_id}
AND	facility_idx = #{facility_idx}
AND	facility_req_idx = #{facility_req_idx}

SELECT
	COUNT(*)
FROM
	FACILITY_REQ
WHERE
	homepage_id = #{homepage_id}
AND	facility_idx = #{facility_idx}
AND apply_id = #{apply_id}
AND	delete_yn = 'N'
AND	apply_status != '3'

