mapper.select:
SELECT A.homepage_id, A.facility_idx, A.facility_req_idx, A.apply_name, REGEXP_REPLACE(A.apply_name, '.', '*', 2) AS masking_name, A.apply_phone, A.apply_status, B.facility_name, B.use_date FROM FACILITY_REQ A, FACILITY_MANAGE B WHERE A.homepage_id = B.homepage_id AND A.facility_idx = B.facility_idx AND A.homepage_id = #{homepage_id} AND A.delete_yn = 'N' AND A.apply_status = '2'
AND #{plan_date} = SUBSTR(B.use_date, 1, 7)
AND B.use_date = #{plan_day}
